\begin{definition}\label{def:symmetric-webs}
The symmetric web category $\mathsf{Web}$ is the
$\mathcal A$-linear strict monoidal category with objects
compositions $\gamma=(\gamma_1,\ldots,\gamma_k)$ of positive
integers, tensor product concatenation and unit the empty
composition. Its generators are splits, merges and invertible
crossings, subject to the local relations below:
\begin{gather*}
\iota_{a+b,(a,b)}=\websplit{a}{b}{a+b},
\mu_{(a,b),a+b}=\webmerge{a}{b}{a+b},
H_{a,b}=
\begin{tikzpicture}[scale=.78,every node/.style={label}]
\draw[a,thickness={b}] (.6,0)..controls(.6,.6)and(-.6,1.2)..(-.6,1.8);
\draw[a,over,thickness={a}] (-.6,0)..controls(-.6,.6)and(.6,1.2)..(.6,1.8);
\node[inputlabel]at(-.6,0){$a$};\node[inputlabel]at(.6,0){$b$};
\node[outputlabel]at(-.6,1.8){$b$};\node[outputlabel]at(.6,1.8){$a$};
\end{tikzpicture},
H_{a,b}^{-1}=
\begin{tikzpicture}[scale=.78,every node/.style={label}]
\draw[a,thickness={b}] (-.6,0)..controls(-.6,.6)and(.6,1.2)..(.6,1.8);
\draw[a,over,thickness={a}] (.6,0)..controls(.6,.6)and(-.6,1.2)..(-.6,1.8);
\node[inputlabel]at(-.6,0){$b$};\node[inputlabel]at(.6,0){$a$};
\node[outputlabel]at(-.6,1.8){$a$};\node[outputlabel]at(.6,1.8){$b$};
\end{tikzpicture}.
\end{gather*}
Here $a,b>0$. Write $\mathsf{Web}_N$ for total thickness
$N=\sum_i\gamma_i$, and $\omega_N=(1,\ldots,1)$ for the
all-thin boundary.
\end{definition}

\begin{lemma}\label{lem:thin-hecke-relations}
The Schur relation at $a=b=c=d=1$ gives
\begin{gather}\label{eq:thin-channel-normalization}
b_i=\webchannel{1}{1}{2}
=\webcross{+}+v\,\webwire{1}\hspace{.6cm}\webwire{1}
=H_i+v.
\end{gather}
(Here $v$ means $v$ times the identity; the latter is often omitted in expressions.)
The crossings satisfy Reidemeister II and III (arbitrary thickness; thin is illustrated below), and
\begin{gather*}
\channelstack{2}=(v+v^{-1})\channelstack{1},\qquad
\AffineWord{2}{1/H,1/h}{2}
=\webwire{1}\hspace{.5cm}\webwire{1},\qquad
\thinword{3}{1/H,2/H,1/H}
=\thinword{3}{2/H,1/H,2/H}.
\end{gather*}
Crossings can be expressed using splits and merges and can
therefore be omitted as generators.
\end{lemma}

\begin{lemma}\label{lem:iterated-web-digons}
Nested digons contract as
\begin{gather*}
\nestedbubble{a}{b}{c}{a+b}{a+b+c}
=\frac{[a+b]!}{[a]![b]!}\webbubble{a+b}{c}{a+b+c},
\qquad
\nestedbubbleright{a}{b}{c}{b+c}{a+b+c}
=\frac{[b+c]!}{[b]![c]!}\webbubble{a}{b+c}{a+b+c}.
\end{gather*}
Both sides evaluate to $[a+b+c]!/([a]![b]![c]!)$ times the
identity.
\end{lemma}

statements.proof_tex:
\begin{proof}
Apply digon removal successively; retained strands are unchanged.
\end{proof}

