\begin{lemma}\label{lem:annular-relations}
Adjoining coils to $\mathsf{Web}$ together with \autoref{Eq:InvCoil} gives
$\mathsf{AWeb}$. On a thin boundary,
\begin{gather*}
X_iX_k=X_kX_i,\qquad H_iX_iH_i=X_{i+1},\qquad
H_iX_k=X_kH_i\quad(k\ne i,i+1).
\end{gather*}
In pictures, (with arbitrary unrelated strands in between or to the left and right)
\begin{gather*}
\thinword{3}{1/H,1/X,1/H}
=\thinword{3}{2/X},\qquad
\thinword{3}{1/H,3/X}
=\thinword{3}{3/X,1/H},\qquad
\thinword{2}{1/X,2/X}
=\thinword{2}{2/X,1/X}.
\end{gather*}
Strands not involved in a relation remain fixed.
\end{lemma}

statements.proof_tex:
\begin{proof}
The coil presentation is \cite[Section~4A]{LTV}.
The displayed relations follow by moving coils across the
cut.
\end{proof}

