\begin{remark}
Annular webs, also called affine webs and other names in the literature, have been studied in various settings; see, e.g., \cite{CK,FominPylyavskyy,LTV,Queffelec,SongWangWebs,SSW}.
\end{remark}

\begin{definition}\label{def:affine-schur-maps}
The affine Schur category $\mathsf{Schur}_N$ has compositions
of $N$ as objects and morphisms
$\Hom_{\mathsf{Schur}_N}(\gamma,\alpha) =\Hom_{\mathcal H_{\rm aff}}(\mathcal M_\gamma,\mathcal M_\alpha),$
with composition of module maps.
\end{definition}

\begin{lemma}\label{lem:affine-schur-dictionary}
The $[A]_v$ and $\theta_A$ form the standard and canonical
bases, respectively. Moreover,
$\operatorname{dimdeg}(A)=\ell(w_A^+)-L_\gamma,$
and the change of basis is
\begin{gather}\label{eq:exact-schur-dictionary}
\theta_A=\sum_{Z:\,w_Z^+\le w_A^+}
v^{\ell(w_A^+)-\ell(w_Z^+)}
P_{w_Z^+,w_A^+}(v^{-2})[Z]_v.
\end{gather}
$\theta_A$ is the unique bar invariant element
with leading term $[A]_v$ and proper coefficients in
$v\mathbb Z[v]$.
\end{lemma}

\begin{remark}
These bases come from \cite{BLM,Du,LusztigAffine}, in the
induced-trivial convention of \cite{Deodhar}; see also \cite{McGerty} 
for a useful summary. They differ
from the elementary ribbon basis of
\cite[Theorem~4.16]{SSW}: a composite web must be expanded
in the standard basis before one can read its KL coefficients. An analogous distinction appears in the classical web calculus:
Khovanov--Kuperberg (KK) showed that the $\mathfrak{sl}_3$ web basis
is not in general dual canonical \cite{KK99}.
\end{remark}

\begin{proposition}\label{cor:dictionary-readout}
The required affine KL coefficient is read from the canonical
web by
\[
\big[[B_m]_v\big]\theta_{A_{j;m}}
=v^{D_{j;m}}P_{w_0,uw_0}(v^{-2}).
\]
In particular,
$[v]\big(\big[[B_m]_v\big]\theta_{A_{j;m}}\big)=\mu_{j;m}.$
\end{proposition}

statements.proof_tex:
\begin{proof}
Apply \autoref{eq:exact-schur-dictionary} with $Z=B_m$.
Since $D_{j;m}$ is odd, the term of degree $(D_{j;m}-1)/2$
in the KL polynomial becomes the coefficient of $v$.
\end{proof}

