ProofComparison.tex:
\newcommand{\ProofComparison}{%
\begin{tikzpicture}[
node distance=2mm and 6mm,
comparison box/.style={
draw=black!25, fill=red!5, rounded corners=2pt,
text width=.43\linewidth, align=center,
inner xsep=5pt, inner ysep=3pt,
font=\normalfont\normalsize
},
comparison heading/.style={
font=\normalfont\bfseries, inner sep=0pt
},
comparison arrow/.style={
-{Stealth[length=1.5mm]}, draw=black!55
}
]
\node[comparison box,minimum height=11mm] (f1)
{Repeat planar web blocks;\\the rank is fixed};
\node[comparison box,minimum height=11mm,right=of f1] (a1)
{Fix the annular web graph;\\vary the rank and thicknesses};

\node[comparison heading,above=3mm of f1] {Finite};
\node[comparison heading,above=3mm of a1] {Affine: this paper};

\node[comparison box,minimum height=16mm,below=of f1] (f2)
{Standard coefficients via FKK:\\
evaluate explicit local maps\\on basis words};
\node[comparison box,minimum height=16mm] (a2) at (a1 |- f2)
{Standard coefficients via Hecke--Schur:\\
count intermediate flags\\to obtain Gaussian polynomials};

\node[comparison box,minimum height=16mm,below=of f2] (f3)
{Correct the blocks on a fixed\\
$28$-dimensional connecting space;\\
prove dual canonicality by local bounds};
\node[comparison box,minimum height=16mm] (a3) at (a1 |- f3)
{Use degree bounds, bar symmetry\\
and positivity to restrict\\canonical terms to six families};

\node[comparison box,minimum height=16mm,below=of f3] (f4)
{Select the required tensor coordinate;\\
reduce the calculation to two states};
\node[comparison box,minimum height=16mm] (a4) at (a1 |- f4)
{The desired terms occur once.\\
Subtract one auxiliary family;\\
four others do not affect degree one.};

\node[comparison box,minimum height=17mm,below=of f4] (f5)
{Two more blocks double the coefficient:\\[2pt]
\mbox{$\mu(x_{2r},y_{2r})=2^r$}};
\node[comparison box,minimum height=17mm] (a5) at (a1 |- f5)
{Gaussian cancellation gives\\[2pt]
\mbox{$\displaystyle
\sum_{j=1}^{m}\mu_{j;m}=\binom{m+1}{2}$}};

\foreach \i/\j in {1/2,2/3,3/4,4/5}{
\draw[comparison arrow] (f\i.south)--(f\j.north);
\draw[comparison arrow] (a\i.south)--(a\j.north);
}
\end{tikzpicture}%
}
